package main

import (
	"fmt"
	"math/big"
	"strings"
)

// lgammaOct emits lgammaOctPieces: log Γ(x) for x in [8, 1024) on 64 pieces
// per octave, in s = x - c (c the piece's centre, a multiple of ulp(x) so
// that s is exact): L(c) as a double-double, a1 (the slope ψ(c), carried to
// double-double because a1 s reaches 54) as a double-double, and the degree-9
// Chebyshev interpolant's remaining terms a2 .. a9 in float64 (a2 s² is below
// 0.03).
func lgammaOct() {
	const (
		emin, emax = 3, 9
		nsub       = 64
		deg        = 7
	)
	o := newOracle()
	c := c200
	lg := evalFn(o, "loggamma", 200)
	worst := new(big.Float).SetPrec(200)
	p("// Code generated by testdata/gen/fitgo lgamma-oct; DO NOT EDIT.")
	p("//")
	p("// lgammaOctPieces: log Γ(x) = L + a1 s + s² (a2 + ... + a7 s^5), s = x - c,")
	p("// for x in [2^%d, 2^%d) on %d pieces per octave; degree-%d Chebyshev", emin, emax+1, nsub, deg)
	p("// interpolants, mpmath %s at 200 bits.", mpmathVersion)
	p("")
	p("package special")
	p("")
	var body strings.Builder
	for e := emin; e <= emax; e++ {
		x0 := new(big.Float).SetPrec(200).SetMantExp(c.i(1), e)
		for k := 0; k < nsub; k++ {
			a := c.mul(x0, c.add(c.i(1), c.quo(c.i(int64(k)), c.i(nsub))))
			b := c.mul(x0, c.add(c.i(1), c.quo(c.i(int64(k+1)), c.i(nsub))))
			pad := c.mul(c.sub(b, a), new(big.Float).SetMantExp(c.i(1), -20))
			cm, co := chebInterp(o, lg, c.sub(a, pad), c.add(b, pad), deg)
			if cm.Cmp(c.quo(c.add(a, b), c.i(2))) != 0 {
				check(fmt.Errorf("centre"))
			}
			// absolute error over the piece, relative to L
			worst = worstRel(o, lg, a, b, cm, co, worst)
			dd := func(v *big.Float) (float64, float64) {
				h := fl(v)
				return h, fl(c.sub(v, c.f(h)))
			}
			lh, ll := dd(co[0])
			a1h, a1l := dd(co[1])
			fmt.Fprintf(&body, "\t// x in 2^%d * [%d/%d, %d/%d]\n", e, nsub+k, nsub, nsub+k+1, nsub)
			fmt.Fprintf(&body, "\t{c: %s, lh: %s, ll: %s, a1: %s, a1l: %s, r: [6]float64{", pyRepr(fl(cm)), pyRepr(lh), pyRepr(ll), pyRepr(a1h), pyRepr(a1l))
			var rs []string
			for i := deg; i >= 2; i-- {
				rs = append(rs, pyRepr(fl(co[i])))
			}
			fmt.Fprintf(&body, "%s}},\n", strings.Join(rs, ", "))
		}
	}
	if worst.Cmp(new(big.Float).SetMantExp(c.i(1), -64)) > 0 {
		check(fmt.Errorf("interpolation error %s", nstr3(worst)))
	}
	p("// Max interpolation error over all pieces: %s relative.", nstr3(worst))
	p("var lgammaOctPieces = [...]lgammaOctPiece{")
	out.WriteString(body.String())
	p("}")
}
